from typing import List

def minRewards(scores: List[int]) -> int:
    n = len(scores)
    if n == 0:
        return 0
    rewards = [1] * n

    # Left to right pass: ensure increasing scores get increasing rewards
    for i in range(1, n):
        if scores[i] > scores[i-1]:
            rewards[i] = rewards[i-1] + 1

    # Right to left pass: ensure decreasing scores get decreasing rewards
    for i in range(n-2, -1, -1):
        if scores[i] > scores[i+1]:
            rewards[i] = max(rewards[i], rewards[i+1] + 1)

    return sum(rewards)

if __name__ == "__main__":
    import sys
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        print(0)
    else:
        scores = list(map(int, input_data))
        print(minRewards(scores))

def common_elements_with_counts(A, B):
    # Count occurrences in A manually
    count_A = {}
    for elem in A:
        if elem in count_A:
            count_A[elem] += 1
        else:
            count_A[elem] = 1

    # Count occurrences in B manually
    count_B = {}
    for elem in B:
        if elem in count_B:
            count_B[elem] += 1
        else:
            count_B[elem] = 1

    # Find unique elements that appear in both lists
    result = []
    for elem in count_A:
        if elem in count_B:
            total_count = count_A[elem] + count_B[elem]
            result.append((elem, total_count))

    return result

def compress_string(s: str) -> str:
    if not s:
        return s

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1

    # Append the last character group
    compressed.append(s[-1] + str(count))

    compressed_str = ''.join(compressed)

    return compressed_str if len(compressed_str) < len(s) else s

def max_subarray_sum(nums):
    if not nums:
        return 0

    current_sum = max_sum = nums[0]

    for num in nums[1:]:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)

    return max_sum

def can_plant_flowers(garden, num_flowers):
    count = 0
    max_count = 0

    for spot in garden:
        if spot == 0:
            count += 1
            max_count = max(max_count, count)
        else:
            count = 0

    return max_count >= num_flowers

