def max_sum_subarray(arr, m):
    if not arr:
        return 0
    n = len(arr)
    # If all numbers are negative, return the largest (closest to zero)
    if all(x < 0 for x in arr):
        return max(arr)

    # Use sliding window with prefix sums for O(n) solution
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + arr[i]

    # We want max(prefix[j] - prefix[i]) for 0 <= i < j <= n and j - i <= m
    # Use deque to maintain minimum prefix values within window of size m
    from collections import deque
    dq = deque()
    max_sum = float('-inf')

    for j in range(1, n+1):
        # Remove indices that are out of window (j - i > m)
        while dq and dq[0] < j - m:
            dq.popleft()

        # If deque not empty, compute candidate sum
        if dq:
            max_sum = max(max_sum, prefix[j] - prefix[dq[0]])

        # Maintain increasing order of prefix values in deque
        while dq and prefix[dq[-1]] >= prefix[j]:
            dq.pop()
        dq.append(j)

    return max_sum

