def max_manhattan_distance(moves: str) -> int:
    x = y = 0
    max_dist = 0
    for move in moves:
        if move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        dist = abs(x) + abs(y)
        if dist > max_dist:
            max_dist = dist
    return max_dist

def calculate_monthly_expenditure(transactions: list, month: str, year: int) -> dict:
    result = {}
    for t in transactions:
        # Extract year and month from the date string
        t_year, t_month, _ = t["date"].split("-")
        if t_year == str(year) and t_month == month and t["type"] == "debit":
            cat = t["category"]
            result[cat] = result.get(cat, 0.0) + t["amount"]
    return result

def optimized_power(base: int, exponent: int, modulo: int = None) -> int:
    # Handle the edge case 0^0 as 1
    if exponent == 0:
        return 1 % modulo if modulo is not None else 1

    # If modulo is provided, reduce base modulo modulo
    if modulo is not None:
        base %= modulo

    result = 1
    current = base
    exp = exponent

    while exp > 0:
        # If current exponent bit is 1, multiply result by current power
        if exp & 1:
            result = result * current
            if modulo is not None:
                result %= modulo
        # Square the current base for the next bit
        current = current * current
        if modulo is not None:
            current %= modulo
        # Move to the next bit
        exp >>= 1

    return result

def longestPalindromeSubseq(s1: str) -> int:
    n = len(s1)
    # dp[i][j] will hold the length of the longest palindromic subsequence in s1[i:j+1]
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the DP table for increasing lengths
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s1[i] == s1[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

