def is_valid_hexadecimal(s: str) -> bool:
    """
    Returns True if the string is a valid hexadecimal number, False otherwise.

    :param s: String, the input string to be checked
    :return: Boolean, True if the string is a valid hexadecimal number, False otherwise
    """
    if not s:
        return False
    # Use all() with a generator for early exit on first invalid character
    return all(c in '0123456789abcdefABCDEF' for c in s)

def most_common_values(lst):
    if not lst:
        return []
    freq = {}
    for x in lst:
        freq[x] = freq.get(x, 0) + 1
    max_count = max(freq.values())
    return [k for k, v in freq.items() if v == max_count]

def character_frequencies(s):
    # Build frequency dictionary for all characters except spaces
    freq = {}
    for ch in s:
        if ch != ' ':
            freq[ch] = freq.get(ch, 0) + 1

    # Find the maximum frequency
    if not freq:
        return ({}, [])

    max_freq = max(freq.values())

    # Collect all characters with that maximum frequency and sort them
    max_chars = sorted([ch for ch, count in freq.items() if count == max_freq])

    return (freq, max_chars)

from collections import deque

def shortest_path(graph: dict[int, list[int]], start: int, end: int) -> int:
    """
    Returns the number of edges in the shortest path from start to end.
    If start == end, returns 0. If no path exists, returns -1.
    """
    if start == end:
        return 0

    # BFS setup
    visited = {start}
    queue = deque([(start, 0)])  # (node, distance)

    while queue:
        current, dist = queue.popleft()
        for neighbor in graph.get(current, []):
            if neighbor == end:
                return dist + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))

    return -1

