def maxProfit(prices: List[int]) -> int:
    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

def max_sum_non_adjacent(arr):
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]

    prev2 = arr[0]          # max sum up to index 0
    prev1 = max(arr[0], arr[1])  # max sum up to index 1

    for i in range(2, len(arr)):
        current = max(prev1, prev2 + arr[i])
        prev2, prev1 = prev1, current

    return prev1

