def word_count(text):
    # Use regex to find all sequences of alphabetic characters (case-insensitive)
    words = re.findall(r'[a-zA-Z]+', text)
    return len(words)

def fibonacci(n):
    """
    Return the nth number in the Fibonacci sequence.
    n is 0-indexed: fibonacci(0) = 0, fibonacci(1) = 1, fibonacci(2) = 1, etc.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0
    a, b = 0, 1
    for _ in range(1, n):
        a, b = b, a + b
    return b

def string_lengths(strings):
    """
    Returns a dictionary mapping strings to their lengths,
    ignoring strings with numbers or special characters,
    and keeping only the first occurrence of duplicates.
    """
    result = {}
    for s in strings:
        # Check if string contains only letters (a-z, A-Z)
        if s.isalpha():
            # Only add if not already present (first occurrence)
            if s not in result:
                result[s] = len(s)
    return result

