def run_length_encoding(data: str) -> str:
    if not data:
        return ""

    result = []
    count = 1
    prev_char = data[0]

    for char in data[1:]:
        if char == prev_char:
            count += 1
        else:
            # Append previous character and its count
            result.append(prev_char)
            result.append(str(count))
            prev_char = char
            count = 1

    # Append the last character and its count
    result.append(prev_char)
    result.append(str(count))

    return ''.join(result)

def first_non_repeating_char(s: str) -> int:
    """
    Returns the index of the first non-repeating character in the string.
    If all characters repeat, returns -1.
    Time complexity: O(n)
    """
    char_count = {}

    # First pass: count occurrences of each character
    for ch in s:
        char_count[ch] = char_count.get(ch, 0) + 1

    # Second pass: find the first character with count 1
    for i, ch in enumerate(s):
        if char_count[ch] == 1:
            return i

    return -1

