def sort_and_combine(s):
    letters = []
    numbers = []
    for ch in s:
        if ch.isalpha():
            letters.append(ch)
        elif ch.isdigit():
            numbers.append(ch)
    # Sort letters case-insensitively, but preserve original case
    letters.sort(key=lambda x: x.lower())
    numbers.sort(key=int)
    return ''.join(letters + numbers)

def checkerboard(n):
    """
    Returns a checkerboard pattern of size n x n using '#' and ' '.
    """
    rows = []
    for i in range(n):
        row = []
        for j in range(n):
            if (i + j) % 2 == 0:
                row.append('#')
            else:
                row.append(' ')
        rows.append(''.join(row))
    return '\n'.join(rows)

def count_words(s):
