    Counts the occurrences of each word in a given string.

    Args:
        s (str): A string containing words separated by spaces.

    Returns:
        dict: A dictionary with words as keys and their counts as values.
    """
    word_counts = {}
    words = s.split()
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    return word_counts

def gnome_sort(arr: list[int]) -> list[int]:
    # Make a copy to avoid mutating the original list
    a = arr[:]
    n = len(a)
    i = 0
    while i < n:
        if i == 0 or a[i] >= a[i - 1]:
            i += 1
        else:
            a[i], a[i - 1] = a[i - 1], a[i]
            i -= 1
    return a

def is_anagram(s: str, t: str) -> bool:
    """
    Returns True if t is an anagram of s, otherwise False.
    """
    # If lengths differ, they cannot be anagrams
    if len(s) != len(t):
        return False

    # Count character frequencies using dictionaries
    count_s = {}
    count_t = {}

    for char in s:
        count_s[char] = count_s.get(char, 0) + 1

    for char in t:
        count_t[char] = count_t.get(char, 0) + 1

    return count_s == count_t


