from typing import List

def minimal_write_sort(arr: List[int]) -> List[int]:
    n = len(arr)
    # Cycle sort: minimize writes by placing each element in its correct position
    # and only writing when necessary.
    for start in range(n - 1):
        item = arr[start]
        # Find where to put the item
        pos = start
        for i in range(start + 1, n):
            if arr[i] < item:
                pos += 1
        # If the item is already in the correct position, skip
        if pos == start:
            continue
        # Skip duplicates
        while item == arr[pos]:
            pos += 1
        # Place the item at its correct position
        arr[pos], item = item, arr[pos]
        # Rotate the rest of the cycle
        while pos != start:
            pos = start
            # Find the correct position for the new item
            for i in range(start + 1, n):
                if arr[i] < item:
                    pos += 1
            # Skip duplicates
            while item == arr[pos]:
                pos += 1
            # Place the item
            arr[pos], item = item, arr[pos]
    return arr

def bubble_sort(arr):
    n = len(arr)
    swap = True

    while swap:
        swap = False
        for i in range(n - 1):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swap = True
    return arr


