class Solution:
    def minStepsToAnagram(self, str1: str, str2: str) -> int:
        # Count frequency of each character in both strings
        freq = [0] * 26

        for ch in str1:
            freq[ord(ch) - ord('a')] += 1
        for ch in str2:
            freq[ord(ch) - ord('a')] -= 1

        # Sum of absolute differences divided by 2 gives the minimum steps
        steps = sum(abs(val) for val in freq) // 2
        return steps

def count_words(strings: list) -> dict:
    """Count the occurrences of each word in a list of strings, case insensitively.

    Args:
        strings: A list of strings.

    Returns:
        A dictionary with words as keys (in lowercase) and their counts as values.
    """
    word_count = {}

    for string in strings:
        words = string.split()
        for word in words:
            word_lower = word.lower()
            if word_lower in word_count:
                word_count[word_lower] += 1
            else:
                word_count[word_lower] = 1

    return word_count

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        char_index = {}
        left = 0
        max_length = 0

        for right, char in enumerate(s):
            if char in char_index and char_index[char] >= left:
                left = char_index[char] + 1
            char_index[char] = right
            max_length = max(max_length, right - left + 1)

        return max_length

def are_anagrams(s1: str, s2: str) -> bool:
