def longest_sequence_length(n, S):
    max_len = 0
    # The length of the sequence can be at most n
    for length in range(1, n + 1):
        # Sum of first 'length' integers: length*(length+1)//2
        base_sum = length * (length + 1) // 2
        if base_sum > S:
            break
        # Check if we can shift the sequence to sum to S
        # S = base_sum + shift * length
        if (S - base_sum) % length == 0:
            shift = (S - base_sum) // length
            if shift + length <= n:
                max_len = length
    return max_len

def max_sum_subarray(arr, k):
    if not arr or k <= 0 or k > len(arr):
        return None  # or raise an exception, depending on requirements

    # Compute sum of first window
    window_sum = sum(arr[:k])
    max_sum = window_sum

    # Slide the window
    for i in range(k, len(arr)):
        window_sum += arr[i] - arr[i - k]
        if window_sum > max_sum:
            max_sum = window_sum

    return max_sum

