from typing import List

def four_sum(arr: List[int], target: int) -> List[List[int]]:
    arr.sort()
    n = len(arr)
    result = []

    for i in range(n - 3):
        # skip duplicate first elements
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            # skip duplicate second elements
            if j > i + 1 and arr[j] == arr[j - 1]:
                continue
            left = j + 1
            right = n - 1
            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]
                if total == target:
                    result.append([arr[i], arr[j], arr[left], arr[right]])
                    # skip duplicates for left and right
                    while left < right and arr[left] == arr[left + 1]:
                        left += 1
                    while left < right and arr[right] == arr[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1
    return result

from typing import List, Union

def split_array_by_pattern(n: int, k: int, arr: List[int], pattern: List[int]) -> Union[List[int], int]:
    # Check if the array can be evenly divided into k parts
    if n % k != 0:
        return -1

    part_len = n // k
    # The pattern length must equal part_len
    if len(pattern) != part_len:
        return -1

    # Check each segment and collect split points
    split_points = []
    for i in range(k):
        start = i * part_len
        # Compare segment with pattern
        if arr[start:start + part_len] != pattern:
            return -1
        if i > 0:
            split_points.append(start + 1)  # 1-based index

    return split_points

