def sum_of_multiples_of_divisors(num: int) -> int:
    """
    Returns the sum of all positive integers less than num that are multiples
    of any divisor of num (excluding num itself).
    """
    if num <= 0:
        return 0

    # Find all divisors of num (excluding num itself)
    divisors = set()
    for i in range(1, int(num**0.5) + 1):
        if num % i == 0:
            divisors.add(i)
            if i != num // i and num // i != num:
                divisors.add(num // i)

    # Sum all numbers less than num that are multiples of any divisor
    total = 0
    for i in range(1, num):
        for d in divisors:
            if i % d == 0:
                total += i
                break  # avoid counting same number multiple times

    return total

