def longest_binary_gap(N: int) -> int:
    """
    Returns the length of the longest binary gap in the binary representation
    of the positive integer N.
    """
    # Convert N to binary string without the '0b' prefix
    binary_str = bin(N)[2:]

    max_gap = 0
    current_gap = 0
    counting = False

    for ch in binary_str:
        if ch == '1':
            if counting:
                # End of a gap: update max if needed
                if current_gap > max_gap:
                    max_gap = current_gap
                current_gap = 0
            else:
                # Start counting after the first '1'
                counting = True
        else:
            if counting:
                # We are inside a potential gap
                current_gap += 1

    return max_gap

def has_repeating_characters(s: str) -> bool:
