def mod_expo(base: int, exponent: int, mod: int) -> int:
    if exponent < 0:
        raise ValueError("Exponent must be positive.")
    if exponent == 0:
        return 1 % mod
    result = 1
    base = base % mod
    while exponent > 0:
        if exponent & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exponent >>= 1
    return result

from typing import List

def wiggle_sort(nums: List[int]) -> None:
    n = len(nums)
    # Quickselect to find median in O(n) average time
    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:
            return nums[left]
        # Choose pivot using median-of-three
        mid = (left + right) // 2
        pivot_val = sorted([nums[left], nums[mid], nums[right]])[1]
        # Partition around pivot_val
        i, j = left, right
        while i <= j:
            while nums[i] < pivot_val:
                i += 1
            while nums[j] > pivot_val:
                j -= 1
            if i <= j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1
        # Now left..j are <= pivot, i..right are >= pivot
        if k <= j:
            return quickselect(left, j, k)
        elif k >= i:
            return quickselect(i, right, k)
        else:
            return nums[k]

    median = quickselect(0, n - 1, n // 2)

    # Virtual indexing: map i -> (1 + 2*i) % (n | 1)
    # This puts larger elements at odd indices, smaller at even indices
    def idx(i: int) -> int:
        return (1 + 2 * i) % (n | 1)

    # Three-way partitioning (Dutch national flag) on virtual indices
    left, i, right = 0, 0, n - 1
    while i <= right:
        if nums[idx(i)] > median:
            nums[idx(i)], nums[idx(left)] = nums[idx(left)], nums[idx(i)]
            left += 1
            i += 1
        elif nums[idx(i)] < median:
            nums[idx(i)], nums[idx(right)] = nums[idx(right)], nums[idx(i)]
            right -= 1
        else:
            i += 1

