def highest_balance_account(transactions):
    balances = {}
    first_occurrence = {}

    for i, (account, trans_type, amount) in enumerate(transactions):
        if account not in first_occurrence:
            first_occurrence[account] = i
        if account not in balances:
            balances[account] = 0

        if trans_type == "deposit":
            balances[account] += amount
        elif trans_type == "withdraw":
            if balances[account] - amount >= 0:
                balances[account] -= amount
            # else ignore the withdrawal

    max_balance = -float('inf')
    best_account = None
    best_index = float('inf')

    for account, balance in balances.items():
        if balance > max_balance:
            max_balance = balance
            best_account = account
            best_index = first_occurrence[account]
        elif balance == max_balance:
            if first_occurrence[account] < best_index:
                best_account = account
                best_index = first_occurrence[account]

    return best_account

def most_frequent_element(nums):
    """
    Returns the most frequent element in a list of integers.
    If there are multiple elements with the same highest frequency,
    returns the smallest one among them.
    """
    if not nums:
        return None

    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    max_freq = max(freq.values())

    # Find the smallest element with the maximum frequency
    result = None
    for num, count in freq.items():
        if count == max_freq:
            if result is None or num < result:
                result = num

    return result

