    for key, value in d.items():
        if isinstance(value, list) and all(isinstance(x, (int, float)) and x > threshold for x in value):
            result[key] = value
    return result

def count_partitions(n: int) -> int:
    """
    Returns the number of integer partitions of n.
    Uses dynamic programming with a 2D table.
    """
    # dp[i][j] = number of ways to partition i using parts <= j
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: there is 1 way to partition 0 (using no parts)
    for j in range(n + 1):
        dp[0][j] = 1

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j > i:
                # If the max part is larger than i, we can't use it
                dp[i][j] = dp[i][i]
            else:
                # Either we don't use part j, or we use it at least once
                dp[i][j] = dp[i][j - 1] + dp[i - j][j]

    return dp[n][n]

