def longest_common_substring(s1: str, s2: str) -> int:
    m, n = len(s1), len(s2)
    # dp[i][j] = length of longest common suffix of s1[:i] and s2[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    max_len = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
            else:
                dp[i][j] = 0

    return max_len

