def findTriplets(arr, target):
    """
    Returns True if there exists a triplet in arr that sums to target, else False.
    Time complexity: O(n^2), Space complexity: O(1)
    """
    n = len(arr)
    arr.sort()  # Sort the array to use two-pointer technique

    for i in range(n - 2):
        # Fix the first element and use two pointers for the remaining part
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

