def convert_value(value):
    """
    Convert a string value based on certain conditions:
    - If value is None, return the string "None"
    - If value can be converted to an integer, return the integer
    - If value can be converted to a float, return the float
    - If value is "true" or "false" (case-insensitive), return boolean
    - Otherwise, return the original string
    """
    if value is None:
        return "None"

    # Try boolean conversion first
    if value.lower() == "true":
        return True
    if value.lower() == "false":
        return False

    # Try integer conversion
    try:
        return int(value)
    except ValueError:
        pass

    # Try float conversion
    try:
        return float(value)
    except ValueError:
        pass

    # Return original string if no conversion applies
    return value


def parse_xml_to_json(element):
    """
    Convert an XML element to a JSON-compatible dictionary.
    Handles nested elements, attributes, and text content.
    """
    result = {}

    # Handle attributes
    if element.attrib:
        result['@attributes'] = {}
        for key, value in element.attrib.items():
            result['@attributes'][key] = convert_value(value)

    # Handle children
    children = list(element)
    if children:
        # Group children by tag name
        child_dict = {}
        for child in children:
            tag = child.tag
            child_data = parse_xml_to_json(child)

            if tag in child_dict:
                # If tag already exists, convert to list if not already
                if not isinstance(child_dict[tag], list):
                    child_dict[tag] = [child_dict[tag]]
                child_dict[tag].append(child_data)
            else:
                child_dict[tag] = child_data

        result.update(child_dict)

    # Handle text content
    text = element.text.strip() if element.text else None
    if text is not None:
        # If element has no children and no attributes, return just the converted value
        if not children and not element.attrib:
            return convert_value(text)
        else:
            result['#text'] = convert_value(text)

    return result


