def find_needle_in_haystack(haystack: str, needle: str) -> int:
    """
    Returns the index of the first occurrence of needle in haystack,
    or -1 if needle is not part of haystack.
    Uses the Knuth-Morris-Pratt (KMP) algorithm.
    """
    n, m = len(haystack), len(needle)

    # Edge case: empty needle is always found at index 0
    if m == 0:
        return 0

    # Step 1: Build the LPS (Longest Prefix which is also Suffix) array for needle
    lps = [0] * m
    length = 0  # length of the previous longest prefix suffix
    i = 1

    while i < m:
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    # Step 2: Perform the actual search using the LPS array
    i = 0  # index for haystack
    j = 0  # index for needle

    while i < n:
        if haystack[i] == needle[j]:
            i += 1
            j += 1
            if j == m:
                # Found a match, return the start index
                return i - j
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    # No match found
    return -1

