def longest_same_parity_subarray(arr):
    """
    Returns the length of the longest contiguous subarray where all elements
    have the same parity (all even or all odd).
    """
    if not arr:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(arr)):
        # Check if current element has same parity as previous
        if (arr[i] % 2) == (arr[i-1] % 2):
            current_len += 1
        else:
            # Reset current streak
            current_len = 1

        # Update maximum length
        if current_len > max_len:
            max_len = current_len

    return max_len

