def coin_change(coins, amount):
    """
    Returns the minimum number of coins needed to make up the given amount.
    If it's not possible, returns -1.
    """
    # Initialize dp array with a large number (amount + 1 is effectively infinity)
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins needed to make amount 0

    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[amount] if dp[amount] != amount + 1 else -1

def is_strictly_increasing(lst: list) -> bool:
    # An empty list or a list with one element is always strictly increasing
    if len(lst) <= 1:
        return True

    # Check each adjacent pair
    for i in range(len(lst) - 1):
        if lst[i] >= lst[i + 1]:
            return False

    return True

def smallest_supersequence(str_a: str, str_b: str) -> int:
    m, n = len(str_a), len(str_b)
    # dp[i][j] = length of shortest common supersequence for str_a[:i] and str_b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str_a[i - 1] == str_b[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

import string

def count_words(sentences: list[str]) -> dict[str, int]:
    """
    Count the occurrences of each word in the given list of sentences.

    Parameters:
    sentences (list[str]): A list of strings containing sentences.

    Returns:
    dict[str, int]: A dictionary mapping each unique word to its count.
    """
    word_count = {}
    translator = str.maketrans('', '', string.punctuation)
    for sentence in sentences:
        words = sentence.translate(translator).lower().split()
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1
    return word_count

from typing import List

def find_easiest_path(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize dp array with the same dimensions as grid
    dp = [[0] * n for _ in range(m)]

    # Starting point
    dp[0][0] = grid[0][0]

    # Fill first column (only possible from above)
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill first row (only possible from left)
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[m-1][n-1]

