def process_transactions(users, transactions):
    # Create a dictionary for quick lookup by name
    user_map = {user["name"]: user for user in users}

    for transaction in transactions:
        parts = transaction.split()
        txn_type = parts[0]

        if txn_type == "DEPOSIT":
            username = parts[1]
            amount = float(parts[2])
            user_map[username]["balance"] += amount

        elif txn_type == "WITHDRAW":
            username = parts[1]
            amount = float(parts[2])
            if user_map[username]["balance"] >= amount:
                user_map[username]["balance"] -= amount

        elif txn_type == "TRANSFER":
            from_user = parts[1]
            to_user = parts[2]
            amount = float(parts[3])
            if user_map[from_user]["balance"] >= amount:
                user_map[from_user]["balance"] -= amount
                user_map[to_user]["balance"] += amount

    # Return sorted list of user dictionaries by name
    return sorted(users, key=lambda x: x["name"])

import os
import shutil

def organize_files_by_extension(directory_path: str) -> dict:
    """
    Organizes files in the given directory by their extensions.
    Creates subdirectories for each extension and moves files accordingly.
    Files without extension are moved to a 'no_extension' subdirectory.
    """
    try:
        # Check if the directory exists
        if not os.path.isdir(directory_path):
            return {
                "success": False,
                "data": f"Directory '{directory_path}' does not exist."
            }

        # List all items in the directory
        items = os.listdir(directory_path)

        # Filter out directories, only process files
        files = []
        for item in items:
            item_path = os.path.join(directory_path, item)
            if os.path.isfile(item_path):
                files.append(item)

        if not files:
            return {
                "success": True,
                "data": "No files to organize."
            }

        # Group files by extension
        extension_map = {}
        for file in files:
            # Get extension (case-insensitive, lowercased)
            _, ext = os.path.splitext(file)
            ext = ext[1:].lower() if ext else "no_extension"

            if ext not in extension_map:
                extension_map[ext] = []
            extension_map[ext].append(file)

        # Create subdirectories and move files
        for ext, file_list in extension_map.items():
            ext_dir = os.path.join(directory_path, ext)
            try:
                os.makedirs(ext_dir, exist_ok=True)
            except PermissionError:
                return {
                    "success": False,
                    "data": f"Permission denied while creating directory '{ext}'."
                }

            for file in file_list:
                src = os.path.join(directory_path, file)
                dst = os.path.join(ext_dir, file)
                try:
                    shutil.move(src, dst)
                except PermissionError:
                    return {
                        "success": False,
                        "data": f"Permission denied while moving file '{file}'."
                    }
                except Exception as e:
                    return {
                        "success": False,
                        "data": f"Error moving file '{file}': {str(e)}"
                    }

        return {
            "success": True,
            "data": "Files organized successfully."
        }

    except PermissionError:
        return {
            "success": False,
            "data": "Permission denied while accessing the directory."
        }
    except Exception as e:
        return {
            "success": False,
            "data": f"An unexpected error occurred: {str(e)}"
        }

