def distinct_prime_factors(n: int) -> int:
    """
    Returns the number of distinct prime factors of a given integer n.
    """
    if n <= 1:
        return 0

    count = 0
    # Handle factor 2 separately to reduce iterations
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n //= 2

    # Check odd factors from 3 upwards
    factor = 3
    while factor * factor <= n:
        if n % factor == 0:
            count += 1
            while n % factor == 0:
                n //= factor
        factor += 2

    # If n is still greater than 1, it is a prime factor
    if n > 1:
        count += 1

    return count

