    print(distinct_prime_factors(97))  # Output: 1 (prime itself)

def shortest_common_supersequence(a: str, b: str) -> str:
    n, m = len(a), len(b)
    # dp[i][j] = length of shortest common supersequence for a[:i] and b[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize base cases
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    # Fill dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1])

    # Reconstruct the supersequence
    i, j = n, m
    result = []
    while i > 0 and j > 0:
        if a[i-1] == b[j-1]:
            result.append(a[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] < dp[i][j-1]:
            result.append(a[i-1])
            i -= 1
        else:
            result.append(b[j-1])
            j -= 1

    # Add remaining characters
    while i > 0:
        result.append(a[i-1])
        i -= 1
    while j > 0:
        result.append(b[j-1])
        j -= 1

    return ''.join(reversed(result))

def processOperations(operations):
    stack = []
    for op in operations:
        if op > 0:
            stack.append(op)
        elif op == 0:
            if not stack:
                return []
            stack.append(stack[-1])
        else:  # op < 0
            n = -op
            if n > len(stack):
                return []
            # pop top n elements
            stack = stack[:-n]
    return stack

def trap_rain_water(heights):
    if not heights:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = 0, 0
    water = 0

    while left < right:
        if heights[left] < heights[right]:
            if heights[left] >= left_max:
                left_max = heights[left]
            else:
                water += left_max - heights[left]
            left += 1
        else:
            if heights[right] >= right_max:
                right_max = heights[right]
            else:
                water += right_max - heights[right]
            right -= 1

    return water

