def bulbSwitch(n: int) -> int:
    """
    Returns the number of bulbs that remain on after n people toggle bulbs.
    Only bulbs at perfect square positions remain on.
    """
    if n <= 0:
        return 0
    return int(math.isqrt(n))

def anagram_words(word1: str, word2: str) -> bool:
