def balance_parentheses(s: str) -> str:
    """
    Removes the minimum number of parentheses to make the string balanced.
    Only '(' and ')' characters are considered.
    """
    # First pass: remove invalid closing parentheses
    open_count = 0
    chars = list(s)
    for i, ch in enumerate(chars):
        if ch == '(':
            open_count += 1
        elif ch == ')':
            if open_count > 0:
                open_count -= 1
            else:
                chars[i] = ''  # mark for removal

    # Second pass: remove excess opening parentheses from the right
    close_count = 0
    for i in range(len(chars) - 1, -1, -1):
        if chars[i] == ')':
            close_count += 1
        elif chars[i] == '(':
            if close_count > 0:
                close_count -= 1
            else:
                chars[i] = ''  # mark for removal

    # Build the result string
    return ''.join(ch for ch in chars if ch != '')

def improved_selection_sort(arr, simulation=False):
    n = len(arr)
    for i in range(n):
        # Assume the array is sorted before this pass
        sorted_flag = True
        min_idx = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
                sorted_flag = False  # found an element out of order
        # If no smaller element was found in the rest, the array is sorted
        if sorted_flag:
            break
        # Swap the found minimum element with the first element
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
        if simulation:
            print(f"iteration {i} : {' '.join(map(str, arr))}")
    if simulation and n == 0:
        print("iteration 0 : ")
    return arr

