def spiralOrder(arr):
    if not arr or not arr[0]:
        return []

    result = []
    top, bottom = 0, len(arr) - 1
    left, right = 0, len(arr[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right along the top row
        for col in range(left, right + 1):
            result.append(arr[top][col])
        top += 1

        # Traverse from top to bottom along the right column
        for row in range(top, bottom + 1):
            result.append(arr[row][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left along the bottom row
            for col in range(right, left - 1, -1):
                result.append(arr[bottom][col])
            bottom -= 1

        if left <= right:
            # Traverse from bottom to top along the left column
            for row in range(bottom, top - 1, -1):
                result.append(arr[row][left])
            left += 1

    return result

def are_isomorphic(str1: str, str2: str) -> bool:
    if len(str1) != len(str2):
        raise ValueError("Strings are of different lengths, cannot be isomorphic")

    mapping_1_to_2 = {}
    mapping_2_to_1 = {}

    for c1, c2 in zip(str1, str2):
        if c1 in mapping_1_to_2:
            if mapping_1_to_2[c1] != c2:
                return False
        else:
            mapping_1_to_2[c1] = c2

        if c2 in mapping_2_to_1:
            if mapping_2_to_1[c2] != c1:
                return False
        else:
            mapping_2_to_1[c2] = c1

    return True

