def make_unique_variables(variable_names: List[str]) -> List[str]:
    counts = {}
    result = []

    for name in variable_names:
        if name not in counts:
            counts[name] = 0
            result.append(name)
        else:
            counts[name] += 1
            suffix = counts[name]
            new_name = f"{name}{suffix}"
            # In case the new_name itself conflicts with an existing original name
            # (e.g., if "apple1" already exists as an original name)
            while new_name in counts:
                suffix += 1
                new_name = f"{name}{suffix}"
            counts[new_name] = 0
            result.append(new_name)

    return result

