def is_prime(n):
    """
    Determines if a number is prime without using any built-in functions or libraries.
    Time complexity: O(sqrt(n))
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    i = 3
    # Check divisibility up to sqrt(n)
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2  # Skip even numbers

    return True

def evaluate_postfix(expression: str) -> float:
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            # Pop two operands
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                result = a / b  # floating-point division

            stack.append(result)
        else:
            # It's a number
            stack.append(float(token))

    return stack[0]

def sum_of_digits(n: int) -> int:
    total = 0
