    Args:
        tuple_list (list of tuple): List of tuples, each containing (key, value).

    Returns:
        dict: Dictionary with keys as first elements and values as lists of second elements.
    """
    result = {}
    for key, value in tuple_list:
        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]
    return result

