def summarize_timestamps(timestamps: List[str]) -> Tuple[Dict[str, Dict[str, str]], int]:
    # Dictionary to store data for each date
    date_data = {}

    for ts in timestamps:
        # Parse the timestamp string into a datetime object
        dt = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S")
        date_str = dt.strftime("%Y-%m-%d")
        time_str = dt.strftime("%H:%M:%S")

        if date_str not in date_data:
            # Initialize entry for this date
            date_data[date_str] = {
                "earliest_time": time_str,
                "latest_time": time_str,
                "count": 1
            }
        else:
            # Update existing entry
            entry = date_data[date_str]
            # Compare times as strings (HH:MM:SS format is lexicographically comparable)
            if time_str < entry["earliest_time"]:
                entry["earliest_time"] = time_str
            if time_str > entry["latest_time"]:
                entry["latest_time"] = time_str
            entry["count"] += 1

    # Number of unique dates
    unique_dates_count = len(date_data)

    return date_data, unique_dates_count

import zlib

def verify_compression_integrity(data: bytes, compression_level: int = -1, checksum_type: str = 'adler32') -> bool:
    # Compute initial checksum
    if checksum_type == 'adler32':
        initial_checksum = zlib.adler32(data)
    elif checksum_type == 'crc32':
        initial_checksum = zlib.crc32(data)
    else:
        raise ValueError("checksum_type must be 'adler32' or 'crc32'")

    # Compress the data
    try:
        compressed = zlib.compress(data, level=compression_level)
    except Exception:
        return False

    # Decompress the data
    try:
        decompressed = zlib.decompress(compressed)
    except Exception:
        return False

    # Compute checksum of decompressed data
    if checksum_type == 'adler32':
        final_checksum = zlib.adler32(decompressed)
    else:
        final_checksum = zlib.crc32(decompressed)

    # Compare checksums
    return initial_checksum == final_checksum

def smallest_missing_positive(nums):
    """
    Returns the smallest positive integer that is not present in the list.
    """
    n = len(nums)
    # Place each number in its correct position if possible
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            # Swap nums[i] with the element at its target index
            target_idx = nums[i] - 1
            nums[i], nums[target_idx] = nums[target_idx], nums[i]

    # Find the first index where the number is not correct
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    # If all numbers from 1 to n are present, the answer is n+1
    return n + 1


