def longest_unique_substring_in_words(s: str) -> int:
    if not s:
        return 0

    words = s.split()
    max_len = 0

    for word in words:
        n = len(word)
        char_set = set()
        left = 0
        for right in range(n):
            while word[right] in char_set:
                char_set.remove(word[left])
                left += 1
            char_set.add(word[right])
            max_len = max(max_len, right - left + 1)

    return max_len

def num_to_bin_str(num: int) -> str:
    """Convert a non-negative integer to its binary representation as a string."""
    if num == 0:
        return "0"

    binary_digits = []
    while num > 0:
        binary_digits.append(str(num % 2))
        num //= 2

    return ''.join(reversed(binary_digits))

