def top_books(ratings: List[Tuple[str, int, float]], min_ratings: int) -> List[str]:
    # Dictionary to store total rating sum and count for each book
    book_stats = {}

    for title, user_id, rating in ratings:
        if title not in book_stats:
            book_stats[title] = [0.0, 0]  # [total_rating, count]
        book_stats[title][0] += rating
        book_stats[title][1] += 1

    # Filter books that meet the minimum rating count
    eligible_books = []
    for title, (total, count) in book_stats.items():
        if count >= min_ratings:
            avg = total / count
            eligible_books.append((title, avg))

    # Sort by descending average, then alphabetically by title
    eligible_books.sort(key=lambda x: (-x[1], x[0]))

    # Return only the titles
    return [title for title, _ in eligible_books]

def compress_path(path: str) -> str:
    """
    Compresses a file path by replacing consecutive identical directory names
    with the name followed by the count.
    """
    if not path:
        return ""

    parts = path.split('/')
    compressed_parts = []

    i = 0
    while i < len(parts):
        current = parts[i]
        count = 1
        # Count consecutive identical parts
        while i + count < len(parts) and parts[i + count] == current:
            count += 1

        if count > 1:
            compressed_parts.append(f"{current}{count}")
            i += count
        else:
            compressed_parts.append(current)
            i += 1

    return '/'.join(compressed_parts)

