def is_palindrome_number(n: int) -> bool:
    if n < 0:
        return False
    original = n
    reversed_num = 0
    while n > 0:
        digit = n % 10
        reversed_num = reversed_num * 10 + digit
        n //= 10
    return original == reversed_num

def min_coins(amount: int, coins: list) -> int:
    # DP array: dp[i] = minimum coins needed to make amount i
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # base case: 0 coins needed for amount 0

    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

def is_water_flow_possible(pipeline: str) -> bool:
    n = len(pipeline)
    # Build adjacency list
    adj = [[] for _ in range(n)]

    for i, ch in enumerate(pipeline):
        if ch == '|':
            if i - 1 >= 0:
                adj[i].append(i - 1)
                adj[i - 1].append(i)
            if i + 1 < n:
                adj[i].append(i + 1)
                adj[i + 1].append(i)
        elif ch == '-':
            if i - 1 >= 0:
                adj[i].append(i - 1)
                adj[i - 1].append(i)
            if i + 1 < n:
                adj[i].append(i + 1)
                adj[i + 1].append(i)
        elif ch == '.':
            if i - 1 >= 0:
                adj[i].append(i - 1)
                adj[i - 1].append(i)
            if i + 1 < n:
                adj[i].append(i + 1)
                adj[i + 1].append(i)
        elif ch == 'A':
            if i - 1 >= 0:
                adj[i].append(i - 1)
                adj[i - 1].append(i)
            if i + 1 < n:
                adj[i].append(i + 1)
                adj[i + 1].append(i)
        elif ch == 'T':
            if i - 1 >= 0:
                adj[i].append(i - 1)
                adj[i - 1].append(i)
            if i + 1 < n:
                adj[i].append(i + 1)
                adj[i + 1].append(i)
        # 'B' has no connections

    # Find all A positions
    sources = [i for i, ch in enumerate(pipeline) if ch == 'A']
    # Find all T positions
    targets = set(i for i, ch in enumerate(pipeline) if ch == 'T')

    # BFS from each source
    for src in sources:
        visited = [False] * n
        stack = [src]
        visited[src] = True
        while stack:
            node = stack.pop()
            if node in targets:
                return True
            for nb in adj[node]:
                if not visited[nb] and pipeline[nb] != 'B':
                    visited[nb] = True
                    stack.append(nb)
    return False

def watch(duration, timeSlots):
    # Use dynamic programming to check if we can sum to duration
    dp = [False] * (duration + 1)
    dp[0] = True  # sum 0 is always possible (choose none)

    for slot in timeSlots:
        for current in range(duration, slot - 1, -1):
            if dp[current - slot]:
                dp[current] = True

    return dp[duration]

def are_anagrams(text1: str, text2: str) -> bool:
    # If lengths differ, they cannot be anagrams
    if len(text1) != len(text2):
        return False

    # Convert to lowercase for case-insensitive comparison
    text1_lower = text1.lower()
    text2_lower = text2.lower()

    # Use character counting with a dictionary (O(n) time, O(1) space since alphabet size is fixed)
    char_count = {}

    # Count characters in text1
    for char in text1_lower:
        char_count[char] = char_count.get(char, 0) + 1

    # Subtract counts using text2
    for char in text2_lower:
        if char not in char_count:
            return False
        char_count[char] -= 1
        if char_count[char] < 0:
            return False

    # All counts should be zero if they are anagrams
    return True

def all_same_parity(numbers):
    if not numbers:
        return True  # empty list considered all same parity
    first_parity = numbers[0] % 2
