    """
    Parses a command string into a structured dictionary.

    Args:
        command: A string command consisting of words separated by spaces.

    Returns:
        A dictionary with keys 'action', 'direction', and/or 'item' as applicable.
        Returns an empty dictionary for invalid commands.
    """
    # Split the command into words and convert to lowercase for case-insensitive parsing
    words = command.lower().strip().split()

