def max_product(nums):
    try:
        # Validate input type
        if not isinstance(nums, list):
            raise TypeError("Input must be a list.")

        # Check if array has at least two elements
        if len(nums) < 2:
            return "Array must contain at least two elements."

        # Find the two largest numbers and two smallest numbers (to handle negatives)
        # We need to consider the product of two largest positives or two smallest negatives
        # because product of two negatives can be positive and large.

        # Initialize variables
        max1 = max2 = float('-inf')
        min1 = min2 = float('inf')

        for num in nums:
            # Update largest two
            if num > max1:
                max2 = max1
                max1 = num
            elif num > max2:
                max2 = num

            # Update smallest two
            if num < min1:
                min2 = min1
                min1 = num
            elif num < min2:
                min2 = num

        # Compute candidate products
        product1 = max1 * max2
        product2 = min1 * min2

        # Return the maximum product
        return max(product1, product2)

    except Exception as e:
        return str(e)

