def trap(height):
    """
    Compute the total amount of rainwater that can be trapped between blocks.

    Args:
        height: List[int] - non-negative integers representing heights of blocks.

    Returns:
        int - total trapped water.
    """
    if not height:
        return 0

    left = 0
    right = len(height) - 1
    left_max = 0
    right_max = 0
    water = 0

    while left < right:
        if height[left] < height[right]:
            if height[left] >= left_max:
                left_max = height[left]
            else:
                water += left_max - height[left]
            left += 1
        else:
            if height[right] >= right_max:
                right_max = height[right]
            else:
                water += right_max - height[right]
            right -= 1

    return water

