    # Directions: 0 = North, 1 = West, 2 = South, 3 = East
    dirs = [(0, 1), (-1, 0), (0, -1), (1, 0)]
    x, y = 0, 0
    direction = 0  # start facing north

    for ch in instructions:
        if ch == 'G':
            dx, dy = dirs[direction]
            x += dx
            y += dy
