def is_perfect_square(x: int) -> bool:
    """
    Returns True if x is a perfect square, otherwise False.
    Handles negative numbers and zero gracefully.
    """
    if x < 0:
        return False
    if x == 0 or x == 1:
        return True

    # Binary search for integer square root
    low, high = 1, x
    while low <= high:
        mid = (low + high) // 2
        square = mid * mid
        if square == x:
            return True
        elif square < x:
            low = mid + 1
        else:
            high = mid - 1
    return False

