def min_operations(word_a: str, word_b: str) -> int:
    n, m = len(word_a), len(word_b)
    # Create a 2D DP table with dimensions (n+1) x (m+1)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base cases: converting to/from empty string
    for i in range(n + 1):
        dp[i][0] = i  # delete all characters from word_a
    for j in range(m + 1):
        dp[0][j] = j  # insert all characters to get word_b

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if word_a[i - 1] == word_b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # no operation needed
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion
                    dp[i][j - 1],      # insertion
                    dp[i - 1][j - 1]   # substitution
                )

    return dp[n][m]

