def longest_common_subsequence(s1: str, s2: str) -> int:
    """
    Returns the length of the longest common subsequence between s1 and s2.
    s2 has all distinct characters.
    Uses patience sorting (LIS on mapped indices) for O(n log n) complexity.
    """
    # Map each character in s2 to its index (0-based)
    char_to_index = {ch: i for i, ch in enumerate(s2)}

    # Build a list of indices from s1 where character exists in s2
    indices = []
    for ch in s1:
        if ch in char_to_index:
            indices.append(char_to_index[ch])

    # Find LIS length on indices (strictly increasing)
    # Patience sorting algorithm
    tails = []  # tails[i] = smallest possible tail value for LIS of length i+1
    for x in indices:
        # Binary search for the first tail >= x
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

def sum_of_primes_below(n):
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i:n:i] = [False] * ((n - 1 - i*i) // i + 1)
    return sum(i for i, is_prime in enumerate(sieve) if is_prime)

