def smallest_subsequence(s: str, k: int) -> str:
    """
    Returns the lexicographically smallest subsequence of length k from s.
    """
    stack = []
    # Count remaining characters for each letter
    from collections import Counter
    remaining = Counter(s)

    for ch in s:
        # While we can pop to make string smaller and still have enough characters left
        while stack and stack[-1] > ch and len(stack) + remaining[ch] > k:
            # We need to pop only if we can still reach length k after popping
            if len(stack) - 1 + remaining[ch] >= k:
                stack.pop()
            else:
                break
        # Push current character if we still need more characters
        if len(stack) < k:
            stack.append(ch)
        remaining[ch] -= 1

    return ''.join(stack)

