def length_of_lis(nums):
    """
    Returns the length of the longest strictly increasing subsequence in nums.
    Uses dynamic programming with binary search for O(n log n) time complexity.
    """
    if not nums:
        return 0

    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []

    for num in nums:
        # Binary search to find the leftmost tails element >= num
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        # If num is larger than all tails, extend the sequence
        if left == len(tails):
            tails.append(num)
        else:
            # Otherwise, replace the first element >= num
            tails[left] = num

    return len(tails)


