def count_occurrences(arr, target):
    """
    Returns the number of occurrences of target in sorted array arr.
    Uses binary search for O(log n) efficiency.
    """
    def find_first():
        """Binary search to find the first occurrence of target."""
        left, right = 0, len(arr) - 1
        first = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                first = mid
                right = mid - 1  # continue searching left
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return first

    def find_last():
        """Binary search to find the last occurrence of target."""
        left, right = 0, len(arr) - 1
        last = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                last = mid
                left = mid + 1  # continue searching right
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return last

    first = find_first()
    if first == -1:
        return 0
    last = find_last()
    return last - first + 1


