def find_duplicate_and_missing(nums):
    n = len(nums)
    # Using XOR method
    xor_all = 0
    for i in range(1, n + 1):
        xor_all ^= i
    for num in nums:
        xor_all ^= num

    # xor_all now equals duplicate ^ missing
    # Find a set bit (rightmost set bit)
    rightmost_set_bit = xor_all & -xor_all

    # Partition numbers into two groups based on that bit
    xor_group1 = 0
    xor_group2 = 0
    for i in range(1, n + 1):
        if i & rightmost_set_bit:
            xor_group1 ^= i
        else:
            xor_group2 ^= i
    for num in nums:
        if num & rightmost_set_bit:
            xor_group1 ^= num
        else:
            xor_group2 ^= num

    # Now xor_group1 and xor_group2 are the two candidates
    # Determine which is duplicate and which is missing
    for num in nums:
        if num == xor_group1:
            return [xor_group1, xor_group2]
        if num == xor_group2:
            return [xor_group2, xor_group1]

    # Fallback (should never reach here)
    return [xor_group1, xor_group2]

