def evaluate_postfix(expression: List[str]) -> int:
    stack = []

    for token in expression:
        if token in ('+', '-', '*', '/'):
            # Pop the two operands (order matters for subtraction and division)
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                # Division truncates toward zero
                result = int(a / b)  # int() truncates toward zero for positive/negative numbers
            stack.append(result)
        else:
            # Operand: convert to integer and push onto stack
            stack.append(int(token))

    # The final result is the only element left on the stack
    return stack[0]

