        max_val = tup[0]
        for item in tup:
            if item > max_val:
                max_val = item
        max_elements.append(max_val)

    # Step 2: Sort the list in decreasing order without built-in sort
    # Using selection sort (descending)
    result = max_elements[:]
    n = len(result)
