    Returns the majority element (appearing more than n/2 times) in the list.
    If no such element exists, returns None.
    """
    # Boyer-Moore majority vote algorithm
    candidate = None
    count = 0

    for num in nums:
        if count == 0:
            candidate = num
            count = 1
        elif num == candidate:
            count += 1
        else:
            count -= 1

    # Verify if candidate is actually the majority element
    if candidate is not None:
        if nums.count(candidate) > len(nums) // 2:
            return candidate
    return None

