def find_min_removals(s: str) -> tuple:
    """
    Returns a tuple (min_removals, valid_string) where min_removals is the
    minimum number of parentheses to remove to make s valid, and valid_string
    is the resulting valid string after removals.
    """
    # First pass: remove invalid closing parentheses
    stack = []
    chars = list(s)
    removals = 0

    for i, ch in enumerate(chars):
        if ch == '(':
            stack.append(i)
        elif ch == ')':
            if stack:
                stack.pop()
            else:
                # invalid closing parenthesis, mark for removal
                chars[i] = ''
                removals += 1

    # Second pass: remove unmatched opening parentheses (those left in stack)
    for idx in stack:
        chars[idx] = ''
        removals += 1

    valid_string = ''.join(ch for ch in chars if ch)
    return (removals, valid_string)

