    if right is None:
        right = len(sorted_list) - 1

    # Base case: if left > right, target is not in the list
    if left > right:
        return -1

    # Calculate the middle index
    mid = (left + right) // 2

    # If target is found at mid, return mid
    if sorted_list[mid] == target:
        return mid
    # If target is smaller than mid, search the left half
    elif target < sorted_list[mid]:
        return recursive_binary_search(sorted_list, target, left, mid - 1)
    # If target is larger than mid, search the right half
    else:
        return recursive_binary_search(sorted_list, target, mid + 1, right)

