def largest_square_root(n: int) -> int:
    """
    Returns the largest integer whose square is less than or equal to n.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 0

    # Binary search for the integer square root
    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        square = mid * mid
        if square == n:
            return mid
        elif square < n:
            low = mid + 1
        else:
            high = mid - 1
    return high

def is_match(s: str, p: str) -> bool:
