def minTravelTime(n, m, edges):
    # Initialize distance matrix with infinity
    INF = 10**9
    dist = [[INF] * n for _ in range(n)]

    # Fill distance matrix from edges (convert to 0-indexed)
    for u, v, w in edges:
        u -= 1
        v -= 1
        dist[u][v] = min(dist[u][v], w)
        dist[v][u] = min(dist[v][u], w)

    # DP table: dp[mask][i] = minimum cost to visit set 'mask' ending at vertex i
    # mask includes the starting vertex (0) and visited vertices
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0  # start at vertex 0, only vertex 0 visited

    # Iterate over all masks
    for mask in range(1 << n):
        # If mask does not include start vertex, skip
        if not (mask & 1):
            continue
        # For each possible current end vertex
        for i in range(n):
            if not (mask & (1 << i)):
                continue
            if dp[mask][i] == INF:
                continue
            # Try to go to an unvisited vertex j
            for j in range(n):
                if mask & (1 << j):
                    continue
                if dist[i][j] == INF:
                    continue
                new_mask = mask | (1 << j)
                new_cost = dp[mask][i] + dist[i][j]
                if new_cost < dp[new_mask][j]:
                    dp[new_mask][j] = new_cost

    # After visiting all vertices, return to start (vertex 0)
    full_mask = (1 << n) - 1
    answer = INF
    for i in range(n):
        if dist[i][0] == INF:
            continue
        if dp[full_mask][i] == INF:
            continue
        answer = min(answer, dp[full_mask][i] + dist[i][0])

    return answer

