def transform_string(s: str) -> str:
    """
    Transforms the input string according to the rules:
    - Letters: next letter in alphabet (z->a, Z->A), preserving case.
    - Digits: complement to 9 (0->9, 1->8, ..., 9->0).
    - Other characters: unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift lowercase letter, wrapping from 'z' to 'a'
            result.append(chr((ord(ch) - ord('a') + 1) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            # Shift uppercase letter, wrapping from 'Z' to 'A'
            result.append(chr((ord(ch) - ord('A') + 1) % 26 + ord('A')))
        elif '0' <= ch <= '9':
            # Complement to 9
            result.append(chr(ord('9') - (ord(ch) - ord('0'))))
        else:
            # Keep other characters unchanged
            result.append(ch)
    return ''.join(result)

