def has_pythagorean_triplet(numbers: List[int]) -> bool:
    # Input validation
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list")
    if len(numbers) < 3:
        raise ValueError("List must contain at least three elements")
    for num in numbers:
        if not isinstance(num, int):
            raise TypeError("All elements must be integers")

    # Square all numbers and store in a set for O(1) lookups
    # We only care about positive numbers for Pythagorean triplets
    squares = {x * x for x in numbers if x > 0}

    # Convert to sorted list of positive numbers for two-pointer approach
    positive_nums = sorted([x for x in numbers if x > 0])

    n = len(positive_nums)
    if n < 3:
        return False

    # For each possible c (largest), check if there exist a,b such that a^2 + b^2 = c^2
    for i in range(n - 1, 1, -1):
        c_sq = positive_nums[i] * positive_nums[i]
        left = 0
        right = i - 1
        while left < right:
            a_sq = positive_nums[left] * positive_nums[left]
            b_sq = positive_nums[right] * positive_nums[right]
            if a_sq + b_sq == c_sq:
                return True
            elif a_sq + b_sq < c_sq:
                left += 1
            else:
                right -= 1

    return False

