def search_in_sorted_matrix(mat: List[List[int]], target: int) -> Tuple[int, int]:
    """
    Search for target in a matrix sorted row-wise and column-wise.
    Returns (row, col) if found, else (-1, -1).
    """
    if not mat or not mat[0]:
        return (-1, -1)

    m, n = len(mat), len(mat[0])
    # Start from top-right corner
    row, col = 0, n - 1

    while row < m and col >= 0:
        current = mat[row][col]
        if current == target:
            return (row, col)
        elif current > target:
            # Move left (decrease column)
            col -= 1
        else:
            # Move down (increase row)
            row += 1

    return (-1, -1)

