def minCompletionTime(tasks: List[int]) -> int:
    total = sum(tasks)
    # DP array: dp[s] = True if sum s can be achieved with some subset
    dp = [False] * (total // 2 + 1)
    dp[0] = True

    for t in tasks:
        # iterate backwards to avoid reusing the same task multiple times
        for s in range(total // 2, t - 1, -1):
            if dp[s - t]:
                dp[s] = True

    # find the largest achievable sum <= total//2
    best = 0
    for s in range(total // 2, -1, -1):
        if dp[s]:
            best = s
            break

    # completion time is max(best, total - best)
    return max(best, total - best)

