def minimize_max_water(arr: List[int]) -> int:
    n = len(arr)
    total = sum(arr)

    # Binary search for the minimal possible maximum
    left, right = 0, max(arr)

    def can_achieve(max_allowed: int) -> bool:
        # Check if we can make all glasses <= max_allowed
        # by moving water left to right
        excess = 0
        for i in range(n):
            if arr[i] + excess > max_allowed:
                excess = arr[i] + excess - max_allowed
            else:
                excess = 0
        # After going left to right, any remaining excess means failure
        if excess > 0:
            return False

        # Now check right to left
        excess = 0
        for i in range(n - 1, -1, -1):
            if arr[i] + excess > max_allowed:
                excess = arr[i] + excess - max_allowed
            else:
                excess = 0
        return excess == 0

    while left < right:
        mid = (left + right) // 2
        if can_achieve(mid):
            right = mid
        else:
            left = mid + 1

    return left

