def max_sliding_window(arr: List[int], k: int) -> List[int]:
    if not arr or k > len(arr):
        return []

    result = []
    dq = deque()  # stores indices of elements in current window

    for i in range(len(arr)):
        # Remove indices that are out of the current window
        if dq and dq[0] < i - k + 1:
            dq.popleft()

        # Remove elements from the back that are smaller than current element
        while dq and arr[dq[-1]] < arr[i]:
            dq.pop()

        dq.append(i)

        # The first element in deque is the maximum for the window
        if i >= k - 1:
            result.append(arr[dq[0]])

    return result

