        return (0, 0, -1)

    best_value = arr[0]
    best_length = 1
    best_start = 0

    current_value = arr[0]
    current_length = 1
    current_start = 0

    for i in range(1, len(arr)):
        if arr[i] == current_value:
            current_length += 1
        else:
            # Check if current run is better than best
            if current_length > best_length:
                best_value = current_value
                best_length = current_length
                best_start = current_start
            # Start new run
            current_value = arr[i]
            current_length = 1
            current_start = i

    # Final check for the last run
    if current_length > best_length:
        best_value = current_value
        best_length = current_length
        best_start = current_start

    return (best_value, best_length, best_start)

