def canReach(arr, start):
    n = len(arr)
    visited = [False] * n
    stack = [start]

    while stack:
        i = stack.pop()
        if arr[i] == 0:
            return True
        if visited[i]:
            continue
        visited[i] = True

        # Move to i + arr[i]
        j = i + arr[i]
        if 0 <= j < n and not visited[j]:
            stack.append(j)

        # Move to i - arr[i]
        j = i - arr[i]
        if 0 <= j < n and not visited[j]:
            stack.append(j)

    return False

