from typing import List, Union

def cholesky_decomposition(A: List[List[float]]) -> Union[List[List[float]], None]:
    n = len(A)
    # Check that A is square
    for row in A:
        if len(row) != n:
            return None

    # Check Hermitian property (A[i][j] == A[j][i]) with tolerance
    for i in range(n):
        for j in range(i, n):
            if abs(A[i][j] - A[j][i]) > 1e-12:
                return None

    V = [[0.0] * n for _ in range(n)]

    for j in range(n):
        # Compute diagonal element V[j][j]
        sum_diag = 0.0
        for k in range(j):
            sum_diag += V[j][k] * V[j][k]

        diag_val = A[j][j] - sum_diag
        if diag_val <= 0:
            return None
        V[j][j] = math.sqrt(diag_val)

        # Compute off-diagonal elements V[i][j] for i > j
        for i in range(j + 1, n):
            sum_off = 0.0
            for k in range(j):
                sum_off += V[i][k] * V[j][k]
            V[i][j] = (A[i][j] - sum_off) / V[j][j]

    return V

