def is_valid_number(s: str) -> bool:
    """
    Determines if a string is a valid number (integer, float, or scientific notation).
    """
    # Strip leading/trailing whitespace
    s = s.strip()
    if not s:
        return False

    # State machine states
    START = 0
    SIGN = 1
    INTEGER = 2
    DOT = 3
    FRACTION = 4
    EXP_SIGN = 5
    EXP_INTEGER = 6
    EXP_START = 7

