    has_digit = False
    has_dot = False
    has_exp = False

    i = 0
    n = len(s)

    while i < n:
        c = s[i]
        if state == START:
            if c in '+-':
                state = SIGN
                i += 1
            elif c.isdigit():
                has_digit = True
                state = INTEGER
                i += 1
            elif c == '.':
                has_dot = True
                state = DOT
                i += 1
            else:
                return False

        elif state == SIGN:
            if c.isdigit():
                has_digit = True
                state = INTEGER
                i += 1
            elif c == '.':
                has_dot = True
                state = DOT
                i += 1
            else:
                return False

        elif state == INTEGER:
            if c.isdigit():
                i += 1
            elif c == '.':
                if has_dot:
                    return False
                has_dot = True
                state = DOT
                i += 1
            elif c in 'eE':
                if has_exp:
                    return False
                has_exp = True
                state = EXP_START
                i += 1
            else:
                return False

        elif state == DOT:
            if c.isdigit():
                has_digit = True
                state = FRACTION
                i += 1
            elif c in 'eE':
                if has_exp:
                    return False
                has_exp = True
                state = EXP_START
                i += 1
            else:
                return False

        elif state == FRACTION:
            if c.isdigit():
                i += 1
            elif c in 'eE':
                if has_exp:
                    return False
                has_exp = True
                state = EXP_START
                i += 1
            else:
                return False

        elif state == EXP_START:
            if c in '+-':
                state = EXP_SIGN
                i += 1
            elif c.isdigit():
                has_digit = True
                state = EXP_INTEGER
                i += 1
            else:
                return False

        elif state == EXP_SIGN:
            if c.isdigit():
                has_digit = True
                state = EXP_INTEGER
                i += 1
            else:
                return False

        elif state == EXP_INTEGER:
            if c.isdigit():
                i += 1
            else:
                return False

        else:
            return False

    # Final validation: must have at least one digit overall
    return has_digit

