def optimized_exchange_sort(arr: List[int]) -> List[int]:
    n = len(arr)
    # Early exit for empty or single-element arrays
    if n <= 1:
        return arr

    # We'll use a flag to detect if the array is already sorted
    # and also to stop early if no swaps occur in a pass.
    # The outer loop goes from 0 to n-2 (like bubble sort optimization)
    for i in range(n - 1):
        swapped = False
        # Inner loop compares and swaps from i+1 to n-1
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
                swapped = True
        # If no swap happened in this pass, the rest is already sorted
        if not swapped:
            break
    return arr

