def find_reachable_nodes(graph: dict, start_node: int) -> list:
    if not graph:
        raise ValueError("graph cannot be empty")
    if start_node not in graph:
        raise ValueError(f"start_node {start_node} is not present in the graph")

    visited = set()

    def dfs(node):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)

    dfs(start_node)
    return sorted(visited)

