def min_weight_difference(n, weights):
    total = sum(weights)
    # Use DP to find subset sums possible
    possible = {0}
    for w in weights:
        new_possible = set()
        for s in possible:
            new_possible.add(s)
            new_possible.add(s + w)
        possible = new_possible
    # Find the best sum closest to half of total
    half = total // 2
    best = 0
    for s in possible:
        if s <= half and s > best:
            best = s
    return total - 2 * best

