def majority_element(nums):
    """
    Returns the majority element (appears more than n//2 times) or None if none exists.
    Uses Boyer-Moore majority vote algorithm for O(n) time and O(1) space.
    """
    # Phase 1: Find candidate
    candidate = None
    count = 0
    for num in nums:
        if count == 0:
            candidate = num
            count = 1
        elif num == candidate:
            count += 1
        else:
            count -= 1

    # Phase 2: Verify candidate
    if candidate is not None:
        occurrences = sum(1 for num in nums if num == candidate)
        if occurrences > len(nums) // 2:
            return candidate
    return None

