import math

def find_nearest_points(points):
    if len(points) < 2:
        raise ValueError("At least two points are required")

    min_dist = float('inf')
    closest_pair = None

    n = len(points)
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            dist = math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)
            if dist < min_dist:
                min_dist = dist
                closest_pair = (points[i], points[j])

    return closest_pair

from typing import List

def canPartition(nums: List[int]) -> bool:
    total_sum = sum(nums)
    # If total sum is odd, cannot partition into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    # dp[i] will be True if a subset with sum i can be formed
    dp = [False] * (target + 1)
    dp[0] = True

    for num in nums:
        # Traverse backwards to avoid using the same element multiple times
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True
        # Early exit if target is already reachable
        if dp[target]:
            return True

    return dp[target]

def first_occurrence(nums, target):
    left, right = 0, len(nums) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            result = mid
            right = mid - 1  # continue searching in left half
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return result

