def trapWater(heights: List[int]) -> int:
    if not heights:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = 0, 0
    water = 0

    while left < right:
        if heights[left] < heights[right]:
            if heights[left] >= left_max:
                left_max = heights[left]
            else:
                water += left_max - heights[left]
            left += 1
        else:
            if heights[right] >= right_max:
                right_max = heights[right]
            else:
                water += right_max - heights[right]
            right -= 1

    return water

def longest_subarray_sum_k(arr, k):
    prefix_sum = 0
    sum_index_map = {}  # stores first occurrence of each prefix sum
    max_len = 0

    for i, num in enumerate(arr):
        prefix_sum += num

        # If the entire prefix sum equals k, subarray from start to i
        if prefix_sum == k:
            max_len = i + 1

        # Check if prefix_sum - k exists in map
        if (prefix_sum - k) in sum_index_map:
            length = i - sum_index_map[prefix_sum - k]
            if length > max_len:
                max_len = length

        # Store first occurrence of this prefix sum
        if prefix_sum not in sum_index_map:
            sum_index_map[prefix_sum] = i

    return max_len

