def is_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, otherwise False.
    Implements optimized primality test.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
