def longest_increasing_subsequence_length(nums):
    """
    Returns the length of the longest increasing subsequence in nums.
    Uses dynamic programming with O(n^2) time complexity.
    """
    if not nums:
        return 0

    n = len(nums)
    # dp[i] = length of LIS ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

