def num_paths(grid):
    """
    Returns the number of distinct paths from top-left to bottom-right
    moving only right or down, avoiding mines (1s).
    """
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])

    # If start or end is a mine, no path possible
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # dp[i][j] = number of ways to reach (i, j)
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0  # mine, no path through here
                continue
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

