    print(convertToTitle(28))   # "AB"
    print(convertToTitle(701))  # "ZY"

import re
from collections import Counter

def most_frequent_word(text):
    # Normalize to lowercase and extract words (ignoring punctuation)
    words = re.findall(r'\b\w+\b', text.lower())

    # Count frequencies while preserving order of first occurrence
    word_counts = Counter(words)

    # Find the maximum frequency
    max_freq = max(word_counts.values())

    # Return the first word that has the maximum frequency
    for word in words:
        if word_counts[word] == max_freq:
            return (word, max_freq)

    # Fallback (should not happen if input is non-empty)
    return ("", 0)

def unique_preserve_order(lst):
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

from typing import List

def trap_water(height: List[int]) -> int:
    if not height:
        return 0

    left, right = 0, len(height) - 1
    left_max, right_max = 0, 0
    water_trapped = 0

    while left < right:
        if height[left] < height[right]:
            if height[left] >= left_max:
                left_max = height[left]
            else:
                water_trapped += left_max - height[left]
            left += 1
        else:
            if height[right] >= right_max:
                right_max = height[right]
            else:
                water_trapped += right_max - height[right]
            right -= 1

    return water_trapped

from typing import List

def rotate_image(matrix: List[List[int]]) -> None:
    """
    Rotates an n x n matrix 90 degrees clockwise in-place.
    """
    if not matrix or not matrix[0]:
        return

    n = len(matrix)

    # Step 1: Transpose the matrix (swap rows and columns)
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Step 2: Reverse each row (mirror horizontally)
    for i in range(n):
        matrix[i].reverse()

def nearest_person(houses):
    n = len(houses)
    result = [float('inf')] * n

    # Left to right pass
    nearest = float('inf')
    for i in range(n):
        if houses[i] == 1:
            nearest = 0
            result[i] = 0
        elif nearest != float('inf'):
            result[i] = min(result[i], i - nearest)
        # Update nearest index if we see a person
        if houses[i] == 1:
            nearest = i

    # Right to left pass
    nearest = float('inf')
    for i in range(n - 1, -1, -1):
        if houses[i] == 1:
            nearest = i
            result[i] = 0
        elif nearest != float('inf'):
            result[i] = min(result[i], nearest - i)

    return result

def find_maximum(numbers):
    if not numbers:
        return None
    max_num = numbers[0]
    for num in numbers[1:]:
        if num > max_num:
            max_num = num
    return max_num

