def isPalindromePermutation(s: str) -> bool:
    # Remove spaces and convert to lowercase
    s = s.replace(" ", "").lower()

    # Count character frequencies
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Count how many characters have odd frequency
    odd_count = 0
    for count in freq.values():
        if count % 2 != 0:
            odd_count += 1

    # Palindrome permutation possible if at most one odd count
    return odd_count <= 1

def canPartition(arr, N):
    total_sum = sum(arr)

    # If total sum is odd, partition is impossible
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2

    # dp[i] will be True if sum i can be formed using some subset
    dp = [False] * (target + 1)
    dp[0] = True

    for num in arr:
        # Traverse backwards to avoid using the same element multiple times
        for s in range(target, num - 1, -1):
            if dp[s - num]:
                dp[s] = True

    return dp[target]

def shiftString(s: str, k: int) -> str:
    # Normalize k to a value in [0, 25]
    k = k % 26
    result = []
    for ch in s:
        # Shift character and wrap around
        shifted = chr((ord(ch) - ord('a') + k) % 26 + ord('a'))
        result.append(shifted)
    return ''.join(result)

def topKFrequent(nums):
    count = {}
    for num in nums:
        if num not in count:
            count[num] = 0 
        count[num] += 1

    # create bucket array where index represents frequency
    bucket = [[] for _ in range(len(nums) + 1)]

    # distribute elements into their respective buckets
    for num, freq in count.items():
        bucket[freq].append(num)

    # sort the bucket in descending order of frequency
    sort_bucket = []
    for i in range(len(bucket)-1, -1, -1):
        if bucket[i]:
            # Sort numbers within the same frequency bucket in ascending order
            # so that smaller numbers come first (as in expected output)
            for num in sorted(bucket[i]):
                sort_bucket.append([num, i])

    return sort_bucket

