def matrix_diagonal_sum(matrix):
    n = len(matrix)
    total = 0
    for i in range(n):
        total += matrix[i][i]  # primary diagonal
        total += matrix[i][n - 1 - i]  # secondary diagonal
    if n % 2 == 1:
        mid = n // 2
        total -= matrix[mid][mid]  # subtract center if odd
    return total

